package app.officinalibri;
import org.junit.*;import org.junit.rules.TemporaryFolder;import org.json.*;import java.io.*;import java.nio.file.*;import java.util.*;import static org.junit.Assert.*;
public class JourneyStoreTest {
 @Rule public TemporaryFolder temporary=new TemporaryFolder();
 private MobileStore store;private DriveFiles drive;private File privateCache;private String bookId;
 @Before public void prepare()throws Exception {File fixture=new File(System.getProperty("officina.driveFixture")),source=new File(new String(Files.readAllBytes(new File(fixture,"root.txt").toPath()),java.nio.charset.StandardCharsets.UTF_8).trim());JSONObject commit=MobileStore.json(new File(fixture,"commit.json"));store=new MobileStore(temporary.newFolder());privateCache=temporary.newFolder();drive=new DriveFiles(privateCache,store);DriveFiles.Transport cloud=new DriveFiles.Transport(){public JSONObject account(){return new JSONObject();}public JSONArray commits(){return new JSONArray();}public String blob(File f,JSONObject r){return "unused";}public String upload(File f,JSONObject r,JSONObject p){return "unused";}public void download(String blob,File target,JSONObject r)throws Exception {Files.copy(new File(source,r.getString("path")).toPath(),target.toPath());}};JSONObject copy=drive.materialize(commit,cloud);bookId=store.accept(copy.getString("id")).getString("id");}
 @Test public void contextMatchesPcAndMetadataIsCopiedIndependently()throws Exception {JourneyStore journeys=new JourneyStore(store);JSONObject state=journeys.load(bookId);String expected=new String(Files.readAllBytes(new File(System.getProperty("officina.driveFixture"),"journey-digest.txt").toPath()),java.nio.charset.StandardCharsets.UTF_8).trim();assertEquals(expected,state.getString("digest"));File file=new File(store.folder(bookId),"percorso.json");String before=MobileStore.hash(file);JSONObject snapshot=drive.snapshot(bookId),clone=drive.cloneBook(bookId,snapshot.getString("digest"));String other=store.accept(clone.getString("id")).getString("id");JSONObject j=journeys.load(other).getJSONObject("journey");j.getJSONObject("brief").put("canon","Nuova decisione sul telefono");journeys.save(other,j);assertEquals(before,MobileStore.hash(file));assertEquals(before,MobileStore.hash(new File(privateCache,"drive-blobs/"+before+".blob")));assertEquals("Nuova decisione sul telefono",journeys.load(other).getJSONObject("journey").getJSONObject("brief").getString("canon"));}
 @Test public void approvalCannotReferToAChangedManuscriptAndHistorySurvives()throws Exception {JourneyStore journeys=new JourneyStore(store);JSONObject state=journeys.load(bookId);JSONObject options=new JSONObject().put("area","testo").put("by","Autrice fixture").put("notes","").put("revision",state.getJSONObject("journey").getInt("revision")).put("expectedDigest",state.getString("digest"));state=journeys.approve(bookId,options);assertEquals(1,state.getJSONObject("journey").getJSONArray("approvals").length());JSONObject novel=store.read(bookId).getJSONObject("novel");novel.getJSONArray("sections").getJSONObject(0).put("title","Modifica di prova");store.save(bookId,novel);options.put("revision",state.getJSONObject("journey").getInt("revision"));try{journeys.approve(bookId,options);fail();}catch(IOException expected){assertTrue(expected.getMessage().contains("libro è cambiato"));}JSONArray history=journeys.history(bookId);assertTrue(history.length()>0);JSONObject restored=journeys.restore(bookId,history.getString(0),state.getJSONObject("journey").getInt("revision"));assertEquals(1,restored.getJSONObject("journey").getJSONArray("approvals").length());assertTrue(journeys.history(bookId).length()>history.length());}
 @Test public void fourReviewsRemainCurrentAcrossSavesButNotCanonChanges()throws Exception {JourneyStore journeys=new JourneyStore(store);JSONObject state=journeys.load(bookId);String digest=state.getString("digest");store.save(bookId,store.read(bookId).getJSONObject("novel"));assertEquals(digest,journeys.load(bookId).getString("digest"));for(String domain:Arrays.asList("tecnica","compositiva","narrativa","autoriale")){state=journeys.review(bookId,new JSONObject().put("domain",domain).put("result","approvata").put("by","Fixture").put("notes","Prova indipendente").put("revision",state.getJSONObject("journey").getInt("revision")).put("expectedDigest",digest));assertEquals(digest,state.getString("digest"));}assertEquals(4,state.getJSONObject("journey").getJSONArray("reviews").length());JSONObject j=state.getJSONObject("journey");j.getJSONObject("brief").put("canon","Regola modificata");state=journeys.save(bookId,j);assertNotEquals(digest,state.getString("digest"));assertEquals(4,state.getJSONObject("journey").getJSONArray("reviews").length());}
 @Test public void invalidProjectAndStaleRevisionDoNotOverwriteMetadata()throws Exception {JourneyStore journeys=new JourneyStore(store);JSONObject old=journeys.load(bookId).getJSONObject("journey"),stale=new JSONObject(old.toString());journeys.save(bookId,old);File f=new File(store.folder(bookId),"percorso.json");String before=MobileStore.hash(f);try{journeys.save(bookId,stale);fail();}catch(IOException expected){}assertEquals(before,MobileStore.hash(f));stale.put("projectId",UUID.randomUUID().toString());try{journeys.save(bookId,stale);fail();}catch(IOException expected){}assertEquals(before,MobileStore.hash(f));try{journeys.restore(bookId,"../../manifest.json",0);fail();}catch(IOException expected){}assertEquals(before,MobileStore.hash(f));}
}
